import assert from 'node:assert/strict'
import { readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import test from 'node:test'
import { gunzipSync } from 'node:zlib'

import type { BrowserAccountSnapshot } from '../../gateway/index.ts'
import { tradeWorkspaceProjection } from '../tradeWorkspace.ts'
import { canonicalJson, cardSummaryFields, type SummaryValue } from '../tradeSummaryShadow.ts'

// The trade-summary goldens (backend repo, gateway-contracts/tests/fixtures/
// trade_summaries, generated by tools/golden/trade_summaries.ts from this
// repo's card code at a893be4; copied from backend commit d36e8091) with the
// fixture snapshots they were generated from (exported by
// trade_summary_golden::export_trade_summary_fixtures). The Rust summaries
// are checked against the same goldens, so a change here that moves a card
// number fails until both sides agree. HEAVY (8 MB compressed) stays in the
// backend repo only.
//
// To refresh after an intended card change: regenerate the goldens there
// with tools/golden/regenerate.sh against this checkout, then copy inputs and
// goldens here (gzip -9 -n).

const FIXTURES = join(import.meta.dirname, 'fixtures', 'trade_summaries')

function readGzipJson(path: string): unknown {
  return JSON.parse(gunzipSync(readFileSync(path)).toString('utf8'))
}

// What the golden generator writes per trade: the card fields, the trade
// id, and whether the coin-level block would turn the trade to attention
// (a second pass with every coin blocked).
function frontendSummaries(snapshot: BrowserAccountSnapshot): Record<string, SummaryValue> {
  const cleared = withBlockedSymbols(snapshot, {})
  const model = tradeWorkspaceProjection(cleared)
  const trades = [...model.activeTrades, ...model.closedTrades]
  const blocked = Object.fromEntries(trades.map((trade) => [trade.symbol, 'coin blocked']))
  const blockedModel = tradeWorkspaceProjection(withBlockedSymbols(snapshot, blocked))
  const blockedLifecycle = new Map(
    [...blockedModel.activeTrades, ...blockedModel.closedTrades].map((trade) => [
      trade.tradeId,
      trade.lifecycle,
    ]),
  )
  const result: Record<string, SummaryValue> = {}
  for (const trade of trades) {
    result[trade.scopeId] = {
      ...cardSummaryFields(trade, cleared.positions),
      trade_id: trade.scopeId,
      coin_block_applies: blockedLifecycle.get(trade.tradeId) === 'attention',
    }
  }
  return result
}

function withBlockedSymbols(
  snapshot: BrowserAccountSnapshot,
  blocked: Record<string, string>,
): BrowserAccountSnapshot {
  return { ...snapshot, checkpoint: { ...snapshot.checkpoint, new_risk_blocked_symbols: blocked } }
}

const fixtures = readdirSync(join(FIXTURES, 'inputs'))
  .filter((name) => name.endsWith('.json.gz'))
  .map((name) => name.slice(0, -'.json.gz'.length))
  .sort()

test('the golden fixtures are all here', () => {
  assert.equal(fixtures.length, 24)
  assert.ok(fixtures.includes('krio_today'))
  assert.ok(fixtures.includes('light'))
})

for (const fixture of fixtures) {
  test(`card math still produces the ${fixture} goldens`, () => {
    const snapshot = readGzipJson(
      join(FIXTURES, 'inputs', `${fixture}.json.gz`),
    ) as BrowserAccountSnapshot
    const golden = readGzipJson(join(FIXTURES, 'goldens', `${fixture}.json.gz`)) as {
      trades: Record<string, SummaryValue>
    }
    const actual = frontendSummaries(snapshot)
    assert.deepEqual(Object.keys(actual).sort(), Object.keys(golden.trades).sort())
    for (const [tradeId, expected] of Object.entries(golden.trades)) {
      const fields = actual[tradeId] as Record<string, SummaryValue>
      for (const [field, value] of Object.entries(expected as Record<string, SummaryValue>)) {
        assert.equal(
          canonicalJson(fields[field] ?? null),
          canonicalJson(value),
          `${fixture} ${tradeId} ${field}`,
        )
      }
      assert.deepEqual(
        Object.keys(fields).sort(),
        Object.keys(expected as Record<string, SummaryValue>).sort(),
        `${fixture} ${tradeId} field set`,
      )
    }
  })
}
